# Hypothesis: find cluster of comps that touch each other (chebyshev adjacency), crop bbox, recolor foreign cells inside bbox to dominant cluster color.
def cc(g,v):
    seen=set(); out=[]
    for y in range(len(g)):
        for x in range(len(g[0])):
            if g[y][x]==v and (y,x) not in seen:
                st=[(y,x)]; seen.add((y,x)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            p=(a+dy,b+dx)
                            if 0<=p[0]<len(g) and 0<=p[1]<len(g[0]) and g[p[0]][p[1]]==v and p not in seen:
                                seen.add(p); st.append(p)
                out.append(comp)
    return out
def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    comps=[]
    for v in set(x for r in g for x in r)-{bg}:
        comps+=cc(g,v)
    # cluster = comps that touch each other (8-adjacency), iterative merge from densest
    cl=[set(c) for c in comps]
    changed=True
    while changed:
        changed=False
        for i in range(len(cl)):
            for j in range(i+1,len(cl)):
                a=next(iter(cl[i])); b=next(iter(cl[j]))
                if max(abs(a[0]-b[0]),abs(a[1]-b[1]))==1:
                    cl[i]|=cl[j]; changed=True
    # choose largest cluster
    big=max(cl,key=len)
    ys=[p[0] for p in big]; xs=[p[1] for p in big]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    out=[]
    dom=Counter(g[y][x] for y,x in big).most_common(1)[0][0]
    for y in range(y0,y1+1):
        row=[]
        for x in range(x0,x1+1):
            v=g[y][x]
            row.append(dom if (y,x) in big else v)
        out.append(row)
    return out
